define([],function(){
'use strict';
const hexToRgb = (hex) => {
    const match = /^#([0-9a-f]{6})$/i.exec(hex || '');
    if (!match) {
        return null;
    }
    const value = parseInt(match[1], 16);
    return [(value >> 16) & 255, (value >> 8) & 255, value & 255];
};

const luminance = (hex) => {
    const rgb = hexToRgb(hex);
    if (!rgb) {
        return 0;
    }
    const channels = rgb.map((value) => {
        const v = value / 255;
        return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    });
    return 0.2126 * channels[0] + 0.7152 * channels[1] + 0.0722 * channels[2];
};

const contrast = (a, b) => {
    const one = luminance(a);
    const two = luminance(b);
    const lighter = Math.max(one, two);
    const darker = Math.min(one, two);
    return (lighter + 0.05) / (darker + 0.05);
};

const init = () => {
    const form = document.getElementById('u-custom-theme-form');
    const preview = document.getElementById('u-theme-live-preview');
    if (!form || !preview) {
        return;
    }

    const fields = {};
    form.querySelectorAll('[data-theme-color]').forEach((input) => {
        fields[input.name] = input;
    });

    const writeScore = (id, value) => {
        const element = document.getElementById(id);
        if (!element) {
            return;
        }
        element.textContent = `${value.toFixed(2)}:1`;
        element.classList.toggle('is-good', value >= 4.5);
        element.classList.toggle('is-bad', value < 4.5);
    };

    const update = () => {
        const values = {};
        Object.keys(fields).forEach((name) => {
            values[name] = fields[name].value.toUpperCase();
            const code = fields[name].closest('label')?.querySelector('code');
            if (code) {
                code.textContent = values[name];
            }
        });

        preview.style.setProperty('--theme-accent', values.accent);
        preview.style.setProperty('--theme-canvas', values.canvas);
        preview.style.setProperty('--theme-surface', values.surface);
        preview.style.setProperty('--theme-text', values.text);
        preview.style.setProperty('--theme-secondary', values.textSecondary);

        writeScore('u-contrast-canvas', contrast(values.text, values.canvas));
        writeScore('u-contrast-surface', contrast(values.text, values.surface));
        writeScore('u-contrast-secondary', contrast(values.textSecondary, values.surface));
        writeScore('u-contrast-dark-canvas', contrast(values.darkText, values.darkCanvas));
        writeScore('u-contrast-dark-secondary', contrast(values.darkTextSecondary, values.darkSurface));
    };

    Object.values(fields).forEach((input) => input.addEventListener('input', update));
    update();
};

return {init:init};
});
